update public.learning_paths
set
  title = 'Race and Ethnicity',
  goal = 'Race and Ethnicity',
  summary = 'Students treat race and ethnicity as social, historical, political, and institutional formations rather than fixed biological facts. The course traces how law, slavery, settler colonialism, immigration, empire, census categories, and citizenship built racial meanings, then how categories are made, remade, contested, and compared. Topics cover intersectionality, prejudice and discrimination, institutional and structural racism, whiteness and racial ideology, group experiences, life-chance institutions, criminal justice, media and identity, anti-racism, and a research-based case study.',
  data = $racejson${"slug": "race-and-ethnicity", "title": "Race and Ethnicity", "description": "Students treat race and ethnicity as social, historical, political, and institutional formations rather than fixed biological facts. The course traces how law, slavery, settler colonialism, immigration, empire, census categories, and citizenship built racial meanings, then how categories are made, remade, contested, and compared. Topics cover intersectionality, prejudice and discrimination, institutional and structural racism, whiteness and racial ideology, group experiences, life-chance institutions, criminal justice, media and identity, anti-racism, and a research-based case study.", "topics": [{"id": "fd0a9ddd-491e-4048-b1fb-a97c79d4d4d5", "type": "topic", "title": "Race, Ethnicity, and the Sociological Imagination", "description": "Students begin by treating race and ethnicity as social, historical, political, and institutional formations rather than fixed biological facts.", "children": [{"id": "1ecf9476-70a0-4f4d-8fb0-28557c8388a9", "type": "subtopic", "title": "Race as social construction", "children": [{"id": "a3a402f6-f9ae-4300-b0fd-815ed8b9a932", "type": "concept", "title": "Biology, ancestry, phenotype, and social classification"}, {"id": "3f3c43e2-8bfe-42ad-ab3b-93ec6a1df1a9", "type": "concept", "title": "Race as category, process, relation, and hierarchy"}, {"id": "d0359101-e29a-455d-a42d-60a8ed3c4411", "type": "concept", "title": "Social facts, lived experience, and institutional consequences"}], "description": "Students learn why race is socially real even though it is not a stable biological essence."}, {"id": "c1d1799d-5f5a-4a96-894c-3224252c885a", "type": "subtopic", "title": "Ethnicity, culture, and boundary-making", "children": [{"id": "fdd7e4a3-5638-4eff-bc18-8a5774ce42ba", "type": "concept", "title": "Language, ancestry, religion, nationality, and culture"}, {"id": "6ae94f14-ce05-4a06-b45f-15f3376dbb31", "type": "concept", "title": "Symbolic ethnicity, panethnicity, and ethnic identity"}, {"id": "c27a9cf7-5767-47e5-9071-d69c4c3d867d", "type": "concept", "title": "Boundary-making, groupness, and belonging"}], "description": "This subtopic distinguishes ethnicity from race while showing how the categories overlap in social life."}, {"id": "e5ad786c-e8ef-47ba-8cf8-250dd0b64a93", "type": "subtopic", "title": "The sociological imagination", "children": [{"id": "a1062f05-7d49-4b74-8f65-21fe41a53e51", "type": "concept", "title": "Biography and social structure"}, {"id": "e29d971c-32e9-4eca-809b-3ec7a6f932fd", "type": "concept", "title": "Micro, meso, and macro levels of analysis"}, {"id": "3bc8a5d6-83d1-4322-a060-1f7cd7878763", "type": "concept", "title": "Reflexivity, positionality, and evidence-based discussion"}], "description": "Students connect personal identities and encounters to history, law, institutions, and power."}]}, {"id": "6ff60372-ef8c-4272-b78d-be262ab0f588", "type": "topic", "title": "The Historical Construction of Race in the United States", "description": "This topic traces how law, slavery, settler colonialism, immigration, empire, census categories, and citizenship built racial meanings and boundaries.", "children": [{"id": "178fa8d9-e446-4ed9-b503-764d829e786b", "type": "subtopic", "title": "Colonialism, slavery, and settler colonialism", "children": [{"id": "73e1cd91-3f43-489d-860b-938314a1038b", "type": "concept", "title": "Indigeneity, conquest, removal, and sovereignty"}, {"id": "832f3afe-cdf7-45ef-bdcb-94127dc3dc52", "type": "concept", "title": "Chattel slavery and hereditary racial status"}, {"id": "27227ca4-828a-4429-a97a-8efc5e138214", "type": "concept", "title": "Colonial classifications and racial capitalism"}], "description": "Students examine race-making as a historical process tied to land, labor, law, and violence."}, {"id": "c7269a6d-185d-4f26-b8cb-3daf64b3ce1a", "type": "subtopic", "title": "Citizenship, law, and racial boundaries", "children": [{"id": "4e196256-aba0-47ae-8a63-c5c14b643dd4", "type": "concept", "title": "Naturalization, citizenship, and immigration law"}, {"id": "20cf5c27-2da0-40ec-a5d3-2c587083c7e9", "type": "concept", "title": "Anti-miscegenation, segregation, and Jim Crow"}, {"id": "58d30daf-928b-4351-b6dc-c46f45884024", "type": "concept", "title": "Census categories and state classification"}], "description": "This subtopic shows how law made racial categories consequential for rights and membership."}, {"id": "ee4d88fd-ebe1-4977-8763-acb9297a7afb", "type": "subtopic", "title": "Civil rights, backlash, and contemporary change", "children": [{"id": "f77203e5-985b-4d8b-98ce-4ae24dcd4c50", "type": "concept", "title": "Reconstruction and civil rights movements"}, {"id": "979f3965-fca4-4f58-be89-cfc80f13e7da", "type": "concept", "title": "Backlash, retrenchment, and color-blind law"}, {"id": "cec822f3-123b-438d-aecd-1fc0d27d6d27", "type": "concept", "title": "Memory, monuments, reparations, and public history"}], "description": "Students connect formal legal change to continuing inequality and political contestation."}]}, {"id": "794853da-7472-46a9-be41-e4c0fbca1d67", "type": "topic", "title": "Racial Formation, Ethnicity, Nationalism, and Comparative Racialization", "description": "Students learn how racial and ethnic categories are made, remade, contested, and compared across groups, places, and historical moments.", "children": [{"id": "51bf81f2-404b-408b-8c12-3a492b97570c", "type": "subtopic", "title": "Racial formation theory", "children": [{"id": "90c12753-b2a8-48e4-b3c5-cd081449cc40", "type": "concept", "title": "Racial projects and racial common sense"}, {"id": "d5afb5e9-8b38-405d-a54e-5879a9fe89ce", "type": "concept", "title": "State, market, school, media, and family as race-making sites"}, {"id": "61f50b1f-a168-42b0-9bfb-e016d6601e68", "type": "concept", "title": "Changing categories over time"}], "description": "Students learn how racial meanings are created through institutions, politics, representation, and everyday practice."}, {"id": "434f9db2-7e43-488e-a471-3504a8139942", "type": "subtopic", "title": "Comparative racialization", "children": [{"id": "5b2b187b-eb57-40bb-bcf5-d4c5f51234b4", "type": "concept", "title": "Differential racialization across groups"}, {"id": "1ae2a433-0b58-418a-9e34-88906c3f3170", "type": "concept", "title": "Linked fate, competition, and coalition"}, {"id": "71826916-ae29-4c95-b512-8fddee085b1a", "type": "concept", "title": "Anti-Blackness, settler colonialism, orientalism, and xenophobia"}], "description": "This subtopic prevents a single-group or single-axis view of race."}, {"id": "3313fcb1-5a1b-42c9-bd95-a4259338e7e6", "type": "subtopic", "title": "Ethnicity, nationalism, and diaspora", "children": [{"id": "c6fc0a8e-76db-4f42-b3dc-e9c287efc3a5", "type": "concept", "title": "Nation-building and imagined communities"}, {"id": "64623dfb-ecc2-4758-86f7-4a4e9a42d400", "type": "concept", "title": "Diaspora, exile, homeland, and transnational ties"}, {"id": "8100a1db-29af-4b70-a74f-c1a87b5230db", "type": "concept", "title": "Ethnic nationalism, pluralism, and multiculturalism"}], "description": "Students analyze how national belonging and ethnic identity shape inclusion and exclusion."}]}, {"id": "e45cb1fb-8ecc-48b2-9078-1f2062ff2f3f", "type": "topic", "title": "Intersectionality: Race, Class, Gender, Sexuality, Disability, Religion, and Immigration", "description": "This section builds the course's central analytic habit: race is never experienced apart from other systems of power and identity.", "children": [{"id": "51b77cef-ba38-44e8-b99d-ead9e07b8a78", "type": "subtopic", "title": "Intersectionality as theory", "children": [{"id": "28090858-1675-49db-8264-18c7ae789777", "type": "concept", "title": "Black feminist origins"}, {"id": "76e9ef7b-6a77-49ee-bd27-87dd5ac77fa1", "type": "concept", "title": "Interlocking systems of oppression"}, {"id": "58e55b7e-16b1-40f7-a70a-a7a4f7df4e33", "type": "concept", "title": "Structural, political, and representational intersectionality"}], "description": "Students learn intersectionality as an analytic framework for power, not a checklist of identities."}, {"id": "ffe5d8e3-653c-4be7-b7e7-715895472fac", "type": "subtopic", "title": "Race, class, and labor", "children": [{"id": "db610a8e-833b-4d06-84c6-9518a8c52430", "type": "concept", "title": "Occupational segregation and wage gaps"}, {"id": "f3600ce9-3785-4443-9b10-225383b4581e", "type": "concept", "title": "Care work, domestic work, agriculture, and service labor"}, {"id": "5e6ca7ef-a2cc-4828-9c98-e86f20bc9001", "type": "concept", "title": "Wealth, debt, inheritance, and mobility"}], "description": "This subtopic links race to stratification, wealth, poverty, and labor-market position."}, {"id": "93f22f7f-4c02-4405-ba51-59e95746e8dd", "type": "subtopic", "title": "Race with gender, sexuality, disability, religion, and immigration", "children": [{"id": "a2048edc-fd38-4754-8c48-224f15b2c862", "type": "concept", "title": "Gendered racism and racialized sexism"}, {"id": "7e7ba59f-6168-4965-890e-25b7b76cd680", "type": "concept", "title": "Queer and trans racialized experience"}, {"id": "c567765a-c610-49ac-a439-04099204dae9", "type": "concept", "title": "Islamophobia, ableism, legal status, and language access"}], "description": "Students practice analyzing how racialization changes across social positions and contexts."}]}, {"id": "5e39d0bb-0473-4374-b009-878069955262", "type": "topic", "title": "Prejudice, Stereotyping, Implicit Bias, Microaggressions, and Discrimination", "description": "Students examine interpersonal and cognitive mechanisms of racial harm while connecting them to larger institutional and cultural patterns.", "children": [{"id": "746df358-71fd-4e32-96a1-cd91c6b7b010", "type": "subtopic", "title": "Prejudice and stereotyping", "children": [{"id": "0bb30ca9-5ad5-429d-a188-1fe0002999b0", "type": "concept", "title": "Explicit attitudes and stereotypes"}, {"id": "a6f51b89-7a04-4750-a1cf-3456f2e45ad6", "type": "concept", "title": "Scapegoating, threat, and social identity"}, {"id": "fb26ea05-aeee-43f8-91f8-f9ca5447de82", "type": "concept", "title": "Stereotype threat and stigma"}], "description": "Students understand how social categories become attached to beliefs, emotions, and expectations."}, {"id": "af42c4a1-8255-4dbf-9f4d-7523cd1e65d4", "type": "subtopic", "title": "Implicit bias and microaggressions", "children": [{"id": "0aa756cb-6958-47a7-8dd0-e47ffb00656b", "type": "concept", "title": "Implicit association and measurement debates"}, {"id": "1a9da8c7-9fdb-4aac-8158-0656baa78c80", "type": "concept", "title": "Everyday exclusions, slights, and cumulative burden"}, {"id": "8d05f116-b258-475e-ac7b-410dc4a4bbf3", "type": "concept", "title": "Intent, impact, repair, and accountability"}], "description": "This subtopic addresses subtle, routine forms of harm while keeping them connected to structure."}, {"id": "562c743a-c83d-462b-b26a-e283ec9ba2b5", "type": "subtopic", "title": "Discrimination and evidence", "children": [{"id": "206ea4f6-8baa-4a86-9475-208511b83082", "type": "concept", "title": "Individual, statistical, and institutional discrimination"}, {"id": "369bd186-f207-4b07-8670-3059f4eb17a4", "type": "concept", "title": "Audit studies and field experiments"}, {"id": "2ae08cb0-d91f-4f11-997a-33bb1d76b78b", "type": "concept", "title": "Legal standards, evidence, and limitations"}], "description": "Students learn to identify discrimination using individual stories, audits, experiments, and institutional data."}]}, {"id": "f350d8d6-e3c0-4a49-8a25-0cc6a906ff28", "type": "topic", "title": "Institutional Racism, Structural Racism, and Systemic Inequality", "description": "This topic moves from individual attitudes to the durable rules, routines, markets, organizations, and policies that reproduce inequality.", "children": [{"id": "ebd03af2-ec4d-44ad-8bf9-57d1328dde49", "type": "subtopic", "title": "Institutional racism", "children": [{"id": "f60a275e-eafd-4876-9c5f-c3abd2ba5668", "type": "concept", "title": "Schools, workplaces, banks, courts, hospitals, and agencies"}, {"id": "4a2ef1e3-1a50-4571-b9fa-b946eaba1aad", "type": "concept", "title": "Rules, discretion, risk assessment, and access"}, {"id": "73234452-5984-4c41-9a76-f7f49238ca6c", "type": "concept", "title": "Organizational culture and accountability"}], "description": "Students learn how organizations reproduce racial inequality through routine procedures rather than only explicit intent."}, {"id": "78254ed7-4cf3-4133-80d4-6c46685275da", "type": "subtopic", "title": "Structural racism", "children": [{"id": "a4c35cb7-681e-49fe-b052-5a1f02672546", "type": "concept", "title": "Feedback loops across housing, education, wealth, health, and policing"}, {"id": "52b56c41-d69f-4a81-a36d-fbcc1851a425", "type": "concept", "title": "Cumulative disadvantage and path dependence"}, {"id": "11ac0db1-3103-4e19-8d5e-92060e2b8955", "type": "concept", "title": "Spatial inequality and neighborhood effects"}], "description": "This subtopic connects institutions into systems that compound advantage and disadvantage."}, {"id": "a22923a9-2827-4095-bcdd-e54fb6e6533a", "type": "subtopic", "title": "Measuring systemic inequality", "children": [{"id": "92f78dd8-25c6-4a58-9e5e-3db889f0eb71", "type": "concept", "title": "Disparity, disproportionality, and discrimination"}, {"id": "b30ec87e-7d32-4090-8368-647654db4c8f", "type": "concept", "title": "Benchmarking and counterfactuals"}, {"id": "5c38f466-1380-46c2-a285-974a4785f8ba", "type": "concept", "title": "Quantitative data with historical and qualitative evidence"}], "description": "Students practice translating broad concepts into data, indicators, and careful claims."}]}, {"id": "ad3fd984-2faa-4983-b2c9-9cc5594c0788", "type": "topic", "title": "Whiteness, White Supremacy, Privilege, Color-Blind Racism, and Racial Ideology", "description": "Students analyze whiteness as a social location, ideological system, institutional advantage, and contested political formation.", "children": [{"id": "fa190ef8-1b7d-446b-95e5-b67ed296aa1d", "type": "subtopic", "title": "Whiteness as social position", "children": [{"id": "8d745ab5-38d6-45e2-9312-f3efcb894353", "type": "concept", "title": "White identity formation"}, {"id": "3b51c2d1-08f3-4872-9b3c-2c2fc9d19559", "type": "concept", "title": "Property, citizenship, space, and belonging"}, {"id": "862b435c-65b4-4b55-bf49-02324234e5b2", "type": "concept", "title": "Invisible norms and institutional advantage"}], "description": "Students study whiteness as historically produced advantage and identity, not as a neutral default."}, {"id": "7ab06937-5298-493a-a070-af2759c303e9", "type": "subtopic", "title": "Racial ideology", "children": [{"id": "c4ad35ee-44d5-4ca7-922d-08e526430833", "type": "concept", "title": "Biological racism, cultural racism, and color-blind racism"}, {"id": "c1ae35ec-7e59-479c-a545-fea21dee1636", "type": "concept", "title": "Meritocracy, individualism, and abstract liberalism"}, {"id": "aa5273df-8ee0-4d17-8dbb-c7e6cef6a117", "type": "concept", "title": "Frames, discourse, and common sense"}], "description": "This subtopic examines how ideas justify, disguise, or challenge racial inequality."}, {"id": "3d367bd4-c6ce-41a9-a0bc-538b7c0ccbb6", "type": "subtopic", "title": "White supremacy and democratic life", "children": [{"id": "7c318717-ca30-4a8f-9165-ba7b0a0d51cd", "type": "concept", "title": "Historical and contemporary white nationalism"}, {"id": "da30affb-24a8-4d0e-94ed-3fa17f7df969", "type": "concept", "title": "Policy, violence, voting, and public institutions"}, {"id": "bfad8cae-a988-4e58-bc7e-4b3e1dcc4dd5", "type": "concept", "title": "Accountability, solidarity, and democratic repair"}], "description": "Students distinguish overt extremist ideology from broader structures of racial domination."}]}, {"id": "dc90e9f1-b108-4cb6-874b-5fc82d9f549e", "type": "topic", "title": "African American Experiences, Anti-Black Racism, and the Black Freedom Struggle", "description": "This section studies Black life, racial capitalism, law, culture, resistance, and freedom movements as central to U.S. society.", "children": [{"id": "7c7b8731-9761-4873-8557-9861530c4626", "type": "subtopic", "title": "Anti-Black racism and racial capitalism", "children": [{"id": "9cf3853e-4ae5-421d-982b-13755abc58c6", "type": "concept", "title": "Slavery, Reconstruction, Jim Crow, and segregation"}, {"id": "d3255179-135b-417d-83b8-f5b57680bb9b", "type": "concept", "title": "Labor markets, wealth extraction, and housing exclusion"}, {"id": "b75899d0-3ac7-4a84-a07e-629587598c95", "type": "concept", "title": "Criminalization and surveillance"}], "description": "Students examine how Black labor, dispossession, surveillance, and exclusion shaped U.S. institutions."}, {"id": "76649aec-6318-4f79-8a1c-8e4c7bdcb914", "type": "subtopic", "title": "Black communities, culture, and intellectual traditions", "children": [{"id": "8462a248-b706-41ba-b2f2-5f2c399205cf", "type": "concept", "title": "Du Bois, Black sociology, and the color line"}, {"id": "6dbacecf-c2cf-43ba-9f16-32040f977e7e", "type": "concept", "title": "Churches, schools, mutual aid, art, and media"}, {"id": "06ccf7d0-a5d4-47d4-aebb-9a39c0894e8d", "type": "concept", "title": "Black feminism and intersectional critique"}], "description": "This subtopic centers agency, creativity, scholarship, and community formation."}, {"id": "9499d093-8c8d-484f-ac10-033c4480705f", "type": "subtopic", "title": "Freedom movements and policy change", "children": [{"id": "d9ae97b1-5952-4c61-8bfb-ee6cdc80b8d6", "type": "concept", "title": "Abolition, civil rights, Black Power, and Black Lives Matter"}, {"id": "bdcc4cdb-b5c7-40ee-933a-81b6c509b6e5", "type": "concept", "title": "Voting rights, education, housing, labor, and policing"}, {"id": "3213c0ba-8422-4bf2-96ea-95c33515a375", "type": "concept", "title": "Coalition, strategy, backlash, and memory"}], "description": "Students connect social movements to institutional transformation and unfinished struggles."}]}, {"id": "4433a6e3-7686-425f-b200-0964d68e6808", "type": "topic", "title": "Latina/o/x Communities, Immigration, Borderlands, Language, and Racialization", "description": "Students study Latinx diversity, migration, citizenship, labor, language, ethnicity, and racial formation beyond simple Black-white binaries.", "children": [{"id": "5c5fd66a-675c-44f9-8d7f-32d029b636fc", "type": "subtopic", "title": "Latinx diversity and racialization", "children": [{"id": "64cc4e72-4438-4085-b19d-20b9b70df534", "type": "concept", "title": "Mexican American, Puerto Rican, Cuban, Central American, Dominican, and South American experiences"}, {"id": "6ad901c2-4e31-4ce9-8193-38b88258a080", "type": "concept", "title": "Mestizaje, Afro-Latinidad, indigeneity, and colorism"}, {"id": "77bb32c8-d2c7-4782-ba32-5e080774db4d", "type": "concept", "title": "Panethnicity and census categories"}], "description": "Students learn why Latinx identity includes many national origins, racial identities, migration histories, and class positions."}, {"id": "cf49c4ee-d1ac-4ee5-9a21-df93f3ced26f", "type": "subtopic", "title": "Immigration, borders, and citizenship", "children": [{"id": "6858e668-d518-4b15-b7a1-fd7c60941cfb", "type": "concept", "title": "Bracero Program, asylum, deportation, and legalization"}, {"id": "201add5f-a02a-4645-be74-d68c8fc213c6", "type": "concept", "title": "Mixed-status families and legal violence"}, {"id": "2ca910ec-9a4a-45b1-b927-b6656304512c", "type": "concept", "title": "Borderlands, militarization, and sanctuary"}], "description": "This subtopic connects Latinx racialization to U.S. empire, labor demand, and border enforcement."}, {"id": "3dd29d82-22d2-4a73-a6b3-f953042105c1", "type": "subtopic", "title": "Language, education, and culture", "children": [{"id": "91bf490e-305e-4e94-bf93-75600f561235", "type": "concept", "title": "English-only politics and bilingual education"}, {"id": "6364cf47-5917-447f-801b-ecda57b01ba0", "type": "concept", "title": "Code-switching, language hierarchy, and accent discrimination"}, {"id": "4dac01e3-82aa-4721-81b9-2a7bb5a0f9cd", "type": "concept", "title": "Cultural production, activism, and representation"}], "description": "Students examine Spanish, bilingualism, schooling, media, and cultural belonging."}]}, {"id": "7a380380-08f7-4f9b-aa1d-2549248d7d5f", "type": "topic", "title": "Asian American, Pacific Islander, Indigenous, Middle Eastern, and Multiracial Experiences", "description": "This topic expands the course through comparative racialization, settler colonialism, model-minority ideology, Islamophobia, indigeneity, and multiracial identity.", "children": [{"id": "ed39ed10-861f-45ab-90f1-1bee04f80aa1", "type": "subtopic", "title": "Asian American and Pacific Islander racialization", "children": [{"id": "47d1f596-ce9a-4778-b53a-6b9568704b1b", "type": "concept", "title": "Chinese Exclusion, Japanese incarceration, refugee histories, and immigration law"}, {"id": "480cf5d9-beb7-4d1b-95a7-cdd0c0daecfc", "type": "concept", "title": "Model minority, perpetual foreigner, and yellow peril"}, {"id": "24ccafbe-bf40-4064-b9ae-60aeb0819f06", "type": "concept", "title": "AAPI diversity, Pacific Islander specificity, and coalition"}], "description": "Students analyze exclusion, labor, empire, model-minority ideology, and anti-Asian violence."}, {"id": "5e00f429-651d-45a4-acbb-4c222c7883a3", "type": "subtopic", "title": "Indigenous peoples and settler colonialism", "children": [{"id": "140f2a20-def6-4edf-8f8b-0799879336e1", "type": "concept", "title": "Tribal sovereignty and nationhood"}, {"id": "c53f0fd0-6bc2-41f0-9a35-da92d4e796d3", "type": "concept", "title": "Removal, allotment, boarding schools, and cultural survival"}, {"id": "ec2714cb-fb70-4dc8-8fae-8a8d881ffe91", "type": "concept", "title": "Land back, treaty rights, and environmental justice"}], "description": "This subtopic treats indigeneity as sovereignty, land, culture, and political relation."}, {"id": "d83b8cab-d0f8-4162-8657-9fd0f792d4e1", "type": "subtopic", "title": "Middle Eastern, North African, Muslim, and multiracial experiences", "children": [{"id": "efe6f450-dab9-40e7-ac63-2ca8686820b2", "type": "concept", "title": "Arab, Middle Eastern, North African, and Muslim racialization"}, {"id": "16573c80-f047-4302-b06b-9045c5f4c56e", "type": "concept", "title": "Islamophobia, surveillance, and security politics"}, {"id": "2e570a96-0371-47df-a619-b82385e9b0f6", "type": "concept", "title": "Multiracial identity, passing, census, and family"}], "description": "Students study categories that reveal the instability and politics of racial classification."}]}, {"id": "959bf611-44e1-4f49-831b-09d6fa2138f9", "type": "topic", "title": "Education, Housing, Wealth, Health, and Environmental Inequality", "description": "Students examine how race and ethnicity shape life chances across key institutions and how policy choices build or reduce disparities.", "children": [{"id": "7d5298c7-0430-4b87-89dc-4a6d6a01869d", "type": "subtopic", "title": "Education and opportunity", "children": [{"id": "2c545bda-0a85-4691-844e-3ab99a7c09f1", "type": "concept", "title": "School segregation and funding"}, {"id": "c3a46612-c90f-4132-ad2c-e162038c1e9d", "type": "concept", "title": "Discipline, tracking, curriculum, and culturally responsive teaching"}, {"id": "63076dd4-8ed9-4a16-a022-13fd4f00a05d", "type": "concept", "title": "College access, student debt, and opportunity gaps"}], "description": "Students examine how schooling can both reproduce and challenge racial inequality."}, {"id": "b4f19de0-e2d3-4f1d-bc22-6e71067dc320", "type": "subtopic", "title": "Housing and wealth", "children": [{"id": "d2a7e2b2-fa53-4c14-9c79-4378a0a3935f", "type": "concept", "title": "Redlining, restrictive covenants, zoning, and appraisal bias"}, {"id": "929dfde0-ed12-4ae4-af6f-af90f43eff8c", "type": "concept", "title": "Homeownership, inheritance, and wealth accumulation"}, {"id": "4d467261-64ba-499e-a4fc-0009e89d6836", "type": "concept", "title": "Eviction, displacement, and neighborhood effects"}], "description": "This subtopic shows how policy created durable racial wealth gaps."}, {"id": "c58e46fe-ecf3-4737-b59e-e9a2231746e8", "type": "subtopic", "title": "Health and environmental inequality", "children": [{"id": "ad3d8c7d-1fd3-4546-bdb6-4513a7234c9e", "type": "concept", "title": "Health disparities and social determinants"}, {"id": "83e5b3a2-178b-449d-898d-90f00f6452da", "type": "concept", "title": "Medical racism, trust, and access"}, {"id": "902de667-e213-464a-9a2f-f682770f5ec5", "type": "concept", "title": "Pollution, climate vulnerability, and environmental racism"}], "description": "Students connect race to embodied inequality, place, exposure, and care."}]}, {"id": "a5ea4a61-5f66-4b1a-b9cb-83ef56304342", "type": "topic", "title": "Criminal Justice, Policing, Punishment, Surveillance, and Legal Inequality", "description": "This section analyzes racial bias and institutional power in policing, courts, sentencing, prisons, surveillance, and reform movements.", "children": [{"id": "a0168533-46ac-40f0-8bca-aade573cb79b", "type": "subtopic", "title": "Policing and surveillance", "children": [{"id": "c7c44745-00e5-4482-92a7-194db7495bf4", "type": "concept", "title": "Stops, searches, arrests, and use-of-force data"}, {"id": "3000c103-3f9e-4954-b2d4-c5df5f7c564e", "type": "concept", "title": "Predictive policing and digital surveillance"}, {"id": "ea6390f2-44f2-430c-b002-514b98159124", "type": "concept", "title": "Community safety, accountability, and abolition debates"}], "description": "Students analyze racialized patterns of police contact, use of force, and surveillance."}, {"id": "20936007-3b4d-4029-9cd6-f57aade6bf6c", "type": "subtopic", "title": "Courts, sentencing, incarceration, and reentry", "children": [{"id": "518231c3-c2e9-4859-8a82-0b6b21c98b02", "type": "concept", "title": "Bail, plea bargaining, sentencing, and prosecutorial discretion"}, {"id": "bffe8aa2-535d-493e-8f6d-49679955c90a", "type": "concept", "title": "Prisons, jails, probation, parole, and collateral consequences"}, {"id": "275386e7-f8c3-477a-b4d6-a33447f95840", "type": "concept", "title": "Reentry, voting rights, family, and employment"}], "description": "This subtopic follows racial inequality across the justice system."}, {"id": "716a1955-44fe-42e1-bdc6-b7abecd8e8b6", "type": "subtopic", "title": "Law, reform, and racial justice", "children": [{"id": "245b71d3-20c4-46f8-9f4a-648a98e82e57", "type": "concept", "title": "Civil rights litigation and consent decrees"}, {"id": "0b15ef66-6710-4bf0-9f7c-90c1fdb8cda0", "type": "concept", "title": "Innocence, wrongful conviction, and forensic reform"}, {"id": "0bade2fe-01f8-40d9-b8e3-32b3f368cb3a", "type": "concept", "title": "Restorative justice, decarceration, and policy evaluation"}], "description": "Students evaluate legal strategies and social movements aimed at changing punitive systems."}]}, {"id": "1db334eb-d7f8-4962-9946-87ccd9eef6c8", "type": "topic", "title": "Media, Culture, Representation, Language, and Identity", "description": "Students learn to analyze how race and ethnicity are narrated, visualized, commodified, resisted, and transformed in public culture.", "children": [{"id": "29b5e19c-a9b1-44f4-9009-54923b732282", "type": "subtopic", "title": "Representation and racial meaning", "children": [{"id": "29dcb462-608d-40b3-adad-2c6e3f1a391b", "type": "concept", "title": "News framing, crime narratives, and moral panic"}, {"id": "4055ef2f-f418-4a13-8303-f4f4cac47024", "type": "concept", "title": "Film, television, music, sport, and advertising"}, {"id": "a63f26b9-b631-4f82-8f60-2111b704ef8e", "type": "concept", "title": "Stereotypes, counter-stories, and visibility"}], "description": "Students learn how media creates, circulates, and contests racial common sense."}, {"id": "320066f8-d795-45ba-b20c-fe7045768147", "type": "subtopic", "title": "Digital culture and racial politics", "children": [{"id": "6ef39a70-b088-4a74-8bde-21319dc0efa9", "type": "concept", "title": "Hashtag activism and digital publics"}, {"id": "d7fc2b07-b068-426d-8e9b-570226c347fe", "type": "concept", "title": "Algorithmic bias, content moderation, and platform governance"}, {"id": "c8041db5-244c-4954-b44b-360b4f614a93", "type": "concept", "title": "Misinformation, hate speech, and online communities"}], "description": "This subtopic examines online spaces as sites of identity, harassment, activism, and surveillance."}, {"id": "dea4dc76-4476-421a-ad5b-9f5713125c73", "type": "subtopic", "title": "Language and identity", "children": [{"id": "62d4b650-a15c-4ee3-a1db-41cbb3a1dd7e", "type": "concept", "title": "Dialect, accent, naming, and respectability politics"}, {"id": "6183629a-a4a3-4937-af53-2d2875ca7a82", "type": "concept", "title": "Code-switching and linguistic profiling"}, {"id": "d61ccc7c-e7f7-4148-914d-3f3b166cb396", "type": "concept", "title": "Inclusive language, naming debates, and self-definition"}], "description": "Students analyze language as a site of race, ethnicity, power, and belonging."}]}, {"id": "b86f070e-be66-430f-a000-43bb51ecf846", "type": "topic", "title": "Anti-Racism, Social Movements, Public Policy, and Organizational Change", "description": "This topic turns analysis toward practice: students evaluate civil rights, racial equity tools, social movements, and institutional change strategies.", "children": [{"id": "22d45c18-47ad-4560-95bb-d789ce7984d2", "type": "subtopic", "title": "Anti-racism and anti-oppressive practice", "children": [{"id": "8a799327-b4b6-41dd-b802-d1d0a9f8e4f2", "type": "concept", "title": "Systemic diagnosis and policy change"}, {"id": "9385c7d9-6eef-484c-b062-23e0db9b60aa", "type": "concept", "title": "Cultural humility and reflective practice"}, {"id": "7aaf1781-6761-44c6-85e3-2fc4bbb318a8", "type": "concept", "title": "Allyship, solidarity, and accountability"}], "description": "Students learn anti-racism as policy, practice, and accountability rather than only personal attitude."}, {"id": "c376415d-4308-4559-99c0-ceba90c3ffae", "type": "subtopic", "title": "Equity-centered policy design", "children": [{"id": "1d6b39fb-9e61-4654-85e1-90016978a1a7", "type": "concept", "title": "Distributional analysis and equity metrics"}, {"id": "4f45c443-d212-46fe-94b4-3928bb45b69a", "type": "concept", "title": "Administrative burden and access barriers"}, {"id": "8737c165-76c0-4b02-a02c-f239ade54f92", "type": "concept", "title": "Participatory and community-centered design"}], "description": "This subtopic introduces tools for evaluating policy effects across groups."}, {"id": "05123d34-12d8-45ca-9152-f962b6a50f8c", "type": "subtopic", "title": "Organizational and movement strategy", "children": [{"id": "5f54c2c8-9d2c-4616-bdff-8e5ee16e0a0f", "type": "concept", "title": "Equity audits and action plans"}, {"id": "e803c5dd-676a-4b28-94ef-3926524ee708", "type": "concept", "title": "Representative bureaucracy and inclusive leadership"}, {"id": "2591322b-0b4c-4ca5-b210-d606999b5513", "type": "concept", "title": "Movement framing, coalition, backlash, and sustainability"}], "description": "Students evaluate how institutions and movements pursue racial justice over time."}]}, {"id": "b1638bfd-4ae1-42f5-a7af-1edaaa65b7a7", "type": "topic", "title": "Contemporary Racial Inequality Capstone: Data, Oral History, Policy, and Community Case Study", "description": "The course culminates in a research-based case study that combines theory, evidence, history, and equity-oriented recommendations.", "children": [{"id": "d783f2c3-2d5e-442a-a210-6b5046253c62", "type": "subtopic", "title": "Research question and case selection", "children": [{"id": "d1046e3a-ead2-4ac4-a7f4-8ed576c470eb", "type": "concept", "title": "Choose an institution, policy, group, neighborhood, movement, or media case"}, {"id": "2c5af74d-1387-4982-b227-ea179dce7c98", "type": "concept", "title": "Define scope, stakeholders, and stakes"}, {"id": "5740ca68-b52a-401f-ba27-d81dc7fcf1c0", "type": "concept", "title": "Connect theory to empirical evidence"}], "description": "Students turn a broad issue into a focused, evidence-based case."}, {"id": "f042c35c-fb2d-4a5b-ad36-0368df1313bc", "type": "subtopic", "title": "Mixed evidence and ethical research", "children": [{"id": "bd01f822-d1da-4b22-b751-83a67799b669", "type": "concept", "title": "Census, Pew, policy, justice, health, education, or housing data"}, {"id": "713e9b2d-a7cc-4e4d-8284-f61cf0938736", "type": "concept", "title": "Oral history, interviews, archives, media, and observation"}, {"id": "bde65e51-3c23-497e-a775-b6b995a86682", "type": "concept", "title": "Consent, harm reduction, citation, and representation"}], "description": "This subtopic teaches students to combine data with history, narrative, and community context responsibly."}, {"id": "4c515afb-cecf-4978-8bd2-af014d2c24e3", "type": "subtopic", "title": "Equity recommendations and presentation", "children": [{"id": "9798f551-61aa-40e8-bb42-2da0fce4c0bc", "type": "concept", "title": "Systems map and causal story"}, {"id": "1cf4a66b-5f71-47a6-9376-24e5e7005c42", "type": "concept", "title": "Policy, organizational, or community recommendations"}, {"id": "7226b068-ef06-475e-9874-7a054c42e879", "type": "concept", "title": "Final dossier, presentation, and reflective learning statement"}], "description": "Students synthesize analysis into a clear, grounded final product."}]}], "dbBacked": true}$racejson$::jsonb,
